insert into public.rule_versions (rule_card_id, version, status, risk_level, title, description, risky_examples, match_patterns, safe_replacements, flag_trigger, safe_fix, source_org, source_title, source_url, source_reference, effective_date, last_verified_at, verification_note, legal_review_status) values ('TR-RY-RESMI-ONAY', 1, 'requires_review', 'high', 'Kamu kurumu onayı veya belge iddiası', 'Bir ürünün kamu kurumu tarafından onaylandığını veya belgelendirildiğini gerçeğe aykırı biçimde ileri sürmek aldatıcıdır; onay varsa kapsamı doğru belirtilmelidir.', array['Sağlık Bakanlığı onaylı', 'TSE onaylı ürün', 'Bakanlık tarafından önerilir']::text[], array['\b(bakanl|tse|tsek|fda)\w*\s+(\S+\s+)?(onayl|onerili|tescilli|sertifikal)\w*', 'bakanl\w*\s+(\S+\s+)?tarafindan\s+(\S+\s+)?(onay|oneril)\w*']::text[], '[]'::jsonb, null, 'Onay veya belge iddiasını yalnızca belge numarası ve kapsamıyla birlikte, gerçekse kullanın; takviye gıdada ''onaylı'' yerine izin/kayıt numarasını yazın.', 'T.C. Resmî Gazete', 'Ticari Reklam ve Haksız Ticari Uygulamalar Yönetmeliğinde Değişiklik Yapılmasına Dair Yönetmelik', 'https://www.resmigazete.gov.tr/eskiler/2026/07/20260701-9.htm', 'Yönetmelik eki haksız ticari uygulamalar listesi (madde numarası teyit edilmedi)', null, '2026-11-17'::date, 'Resmî metin bu güncellemede okunmadı; kural yaygın uygulamaya ve ikincil kaynaklara göre yazıldı. Doğrulanana kadar yalnızca bilgilendirme amaçlıdır.', 'pending')
  on conflict (rule_card_id, version) do nothing;

