insert into public.rule_versions (rule_card_id, version, status, risk_level, title, description, risky_examples, match_patterns, safe_replacements, flag_trigger, safe_fix, source_org, source_title, source_url, source_reference, effective_date, last_verified_at, verification_note, legal_review_status) values ('TR-TAKVIYE-ILAC-IZLENIMI', 1, 'requires_review', 'high', 'Takviye gıdada ilaç izlenimi', 'Takviye gıdalar ilaç değildir; reklamda ilaç gibi etki ettiği, ilacın yerine geçtiği veya hastalığı önlediği izlenimi verilemez.', array['İlaç gibi etki eder', 'İlaçlarınızı bırakın', 'Hastalıklara karşı korur']::text[], array['ilac\w*\s+(gibi|yerine|etkisi)', 'ilac\w*\s+(\S+\s+)?birak\w*', 'hastalik\w*\s+(\S+\s+)?(korur|onler)\w*']::text[], '[]'::jsonb, null, 'Ürünü içerik ve kullanım şekliyle anlatın; ''takviye gıdalar ilaç değildir'' uyarısını görünür kullanın.', 'T.C. Resmî Gazete', 'Ticari Reklam ve Haksız Ticari Uygulamalar Yönetmeliğinde Değişiklik Yapılmasına Dair Yönetmelik', 'https://www.resmigazete.gov.tr/eskiler/2026/07/20260701-9.htm', 'Takviye gıda reklamları (Tarım ve Orman Bakanlığı düzenlemesi; teyit edilmedi)', null, '2026-11-17'::date, 'Resmî metin bu güncellemede okunmadı; kural yaygın uygulamaya ve ikincil kaynaklara göre yazıldı. Doğrulanana kadar yalnızca bilgilendirme amaçlıdır.', 'pending')
